input_grid = [
    [0, 6, 0, 0, 0, 5, 0, 5],
    [0, 6, 0, 0, 0, 0, 0, 5],
    [6, 0, 0, 0, 5, 5, 0, 0],
    [6, 6, 0, 6, 0, 0, 0, 5]
]

# Pattern hypothesis: Columns with single non-zero value get filled uniformly
# Empty columns (2, 6) get filled based on neighbors

# Col-by-col "filled" version (uniform fill for non-zero columns, empty stay empty)
filled_uniform = []
for c in range(8):
    col_vals = [input_grid[r][c] for r in range(4)]
    nz = [v for v in col_vals if v != 0]

    if not nz:
        filled_uniform.append([0] * 4)  # empty column
    else:
        filled_uniform.append([nz[0]] * 4)  # uniform fill

print("Uniform fill (empty columns stay empty):")
for row in filled_uniform:
    print(row)

# Alternative: Empty columns get filled by closest neighbor
filled_full = []
for c in range(8):
    col_vals = [input_grid[r][c] for r in range(4)]
    nz = [v for v in col_vals if v != 0]

    if not nz:
        # Find closest non-empty neighbor
        left = next((v for c2 in range(c) for r in range(4) if input_grid[r][c2] != 0), None)
        right = next((v for c2 in range(c+1, 8) for r in range(4) if input_grid[r][c2] != 0), None)
        if left and right and left == right:
            val = left
        elif left:
            val = left
        elif right:
            val = right
        else:
            continue
        filled_full.append([val] * 4)
    else:
        filled_full.append([nz[0]] * 4)

print("\nFull fill (empty columns filled by nearest neighbor):")
for row in filled_full:
    print(row)
